6	
7	/**
8	 * A simple predator-prey simulator, based on a rectangular field
9	 * containing Seaweed, Salmon, Cod, Shark, Whale, and also the elmement of disease and weather
10	 *
11	 * @version 2022/03/02
12	 */
13	public class Simulator
14	{
15	    // Constants representing configuration information for the simulation.
16	    // The default width for the grid.
17	    private static final int DEFAULT_WIDTH = 120;
18	    // The default depth of the grid.
19	    private static final int DEFAULT_DEPTH = 80;
20	
21	    // The probability that a fox will be created in any given grid position.
22	    private static final double SALMON_CREATION_PROBABILITY = 0.08;
23	    // The probability that a rabbit will be created in any given grid position.
24	    private static final double COD_CREATION_PROBABILITY = 0.08;  
25	    // The probability that a seaweed will be created in any given grid position.
26	    private static final double SEAWEED_CREATION_PROBABILITY = 0.03;
27	    // The probability that a shark will be created in any given grid position.
28	    private static final double SHARK_CREATION_PROBABILITY = 0.04;
29	    // The probability that a whale will be created in any given grid position.
30	    private static final double WHALE_CREATION_PROBABILITY = 0.03;
31	
32	    // The probability that a storm may occur.
33	    private static final double STORM_HAPPEN_PROBABILITY = 0.14; 
34	    // The probability that the disease may occur.
35	    private static final double DISEASE_PROBABILITY = 0.1;
36	
37	
38	    // List of creatures in the field.
39	    private List<Creature> creatures;
40	    // The current state of the field.
41	    private Field field;
42	    // The current step of the simulation.
43	    private int step;
44	    // A graphical view of the simulation.
45	    private SimulatorView view;
46	    private Disease disease;
47	    private Weather weather;
48	
49	    
50	    // The inital level of dissolved oxygen in the water. 
51	    private double oxygenLevel; 
52	
53	    /**
54	     * Construct a simulation field with default size.
55	     */
56	    public Simulator()
57	    {
58	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
59	    }
60	
61	    /**
62	     * Create a simulation field with the given size.
63	     * @param depth Depth of the field. Must be greater than zero.
64	     * @param width Width of the field. Must be greater than zero.
65	     */
66	    public Simulator(int depth, int width)
67	    {
68	        if(width <= 0 || depth <= 0) {
69	            System.out.println("The dimensions must be greater than zero.");
70	            System.out.println("Using default values.");
71	            depth = DEFAULT_DEPTH;
72	            width = DEFAULT_WIDTH;
73	        }
74	
75	        creatures = new ArrayList<>();
76	
77	        field = new Field(depth, width);
78	        weather = new Weather(field);
79	        disease = new Disease();
80	
81	        oxygenLevel = 1;
82	
83	
84	        // Create a view of the state of each location in the field.
85	        view = new SimulatorView(depth, width);
86	
87	        view.setColor(Cod.class, Color.ORANGE);
88	        view.setColor(Salmon.class, Color.YELLOW);
89	        view.setColor(Seaweed.class, Color.RED);
90	        view.setColor(Shark.class, Color.BLACK);
91	        view.setColor(Whale.class, Color.PINK);
92	        view.setColor(Weather.class,Color.BLUE);
93	
94	        // Setup a valid starting point.
95	        reset();
96	    }
97	
98	    /**
99	     * Run the simulation from its current state for a reasonably long period,
100	     * (1000 steps).
101	     */
102	    public void runLongSimulation()
103	    {
104	        simulate(1000);
105	    }
106	
107	    /**
108	     * Run the simulation from its current state for the given number of steps.
109	     * Stop before the given number of steps if it ceases to be viable.
110	     * @param numSteps The number of steps to run for.
111	     */
112	    public void simulate(int numSteps)
113	    {
114	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
115	            simulateOneStep();
116	            delay(60);   // uncomment this to run more slowly
117	        }
118	    }
119	
120	    /**
121	     * Run the simulation from its current state for a single step.
122	     * 
123	     * Iterate over the whole field updating the state of each
124	     * creaturesÃ¯Â¼Ârecord the total amount of oxygen that is consumed or produced 
125	     * by specific species in each step, Storms have a certain probability of occurring�, 
126	     * update the oxygen level, and identify if the disease is stops.
127	     */
128	    public void simulateOneStep()
129	    {
130	        step++;
131	
132	        double totalOxygenInvolved= 0; //oxygen that is generated or consumed in total for this step
133	
134	        disease.creationSourceOfInfection(creatures, step);
135	
136	        // Provide space for newborn animals.
137	        List<Creature> newCreatures = new ArrayList<>();        
138	        // Let all creatures act.
139	        for(Iterator<Creature> it = creatures.iterator(); it.hasNext(); ) {
140	            Creature creature = it.next();
141	            totalOxygenInvolved += creature.act(newCreatures, timeOfDay(), oxygenLevel, disease, step);
142	            if(!creature.isAlive()) {
143	                it.remove();
144	            }
145	        }
146	
147	        if(Randomizer.getRandom().nextDouble() <= STORM_HAPPEN_PROBABILITY) {
148	            weather.underwaterStorm(3); //  generate the storm at a random location.
149	            weather.setStormStart(true);
150	        } else {
151	            weather.setStormStart(false);
152	        }        
153	
154	        // calculate the oxygen left
155	        oxygenLevel += totalOxygenInvolved;
156	
157	        // identify if disease stops
158	        if(disease.getIsSpread()){
159	            disease.setIsSpread(identifyIfDiseaseStops());
160	        }
161	
162	        // Add the newly born creatures to the main lists.
163	        creatures.addAll(newCreatures);
164	        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
165	    }
166	
167	    /**
168	     * Reset the simulation to a starting position.
169	     */
170	    public void reset()
171	    {
172	        step = 0;
173	        creatures.clear();
174	        populate();
175	        oxygenLevel = 1;
176	        Animal.populationDieOfDisease = 0;
177	
178	        // Show the starting state in the view.
179	        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
180	    }
181	
182	    /**
183	     * Randomly populate the field with Salmon, Seaweed, Shark and Whale.
184	     * notice if and else if is based on the creation probability of a creature in an ascending order
185	     */
186	    private void populate()
187	    {
188	        Random rand = Randomizer.getRandom();
189	        field.clear();
190	        for(int row = 0; row < field.getDepth(); row++) {
191	            for(int col = 0; col < field.getWidth(); col++) {
192	                if(rand.nextDouble() <= SALMON_CREATION_PROBABILITY) {
193	                    Location location = new Location(row, col);
194	                    Salmon salmon = new Salmon(true, field, location);
195	                    creatures.add(salmon);
196	                }
197	                else if(rand.nextDouble() <= COD_CREATION_PROBABILITY) {
198	                    Location location = new Location(row, col);
199	                    Cod cod = new Cod(true, field, location);
200	                    creatures.add(cod);
201	                }
202	                else if(rand.nextDouble() <= SEAWEED_CREATION_PROBABILITY){
203	                    Location location = new Location (row, col);
204	                    Seaweed seaweed = new Seaweed(true, field, location);
205	                    creatures.add(seaweed);
206	                }else if(rand.nextDouble() <= SHARK_CREATION_PROBABILITY) {
207	                    Location location = new Location(row, col);
208	                    Shark shark = new Shark(true, field, location);
209	                    creatures.add(shark);
210	                }else if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
211	                    Location location = new Location(row, col);
212	                    Whale whale = new Whale(true, field, location);
213	                    creatures.add(whale);
214	                }
215	                // else leave the location empty.
216	            }
217	        }
218	    }
219	
220	    /**
221	     *  Pause for a given time.
222	     *  @param millisec  The time to pause for, in milliseconds
223	     */
